#!/usr/bin/env python3
"""[MEDIÇÃO] TD-029 R8.5c (Linux) — NÃO MERGEAR. Mutantes L1–L6 da ronda 14 (formas exatas, raiz → RAIZ_SYSFS).
Uso: python3 -I mutantes.py aplica <ID> <raiz>  |  python3 -I mutantes.py teste <ID>"""
import json, sys
M = json.loads('{"L1": ["const RAIZ_SYSFS: &str = \\"/sys/class/net\\";", "const RAIZ_SYSFS: &str = \\"/sys/class/nett\\";", "r85c_l6_raiz_e_sys_class_net"], "L2": ["#[cfg(target_os = \\"linux\\")]\\nfn probe_linux() -> Result<(), NetworkPolicyError> {\\n    probe_sysfs(std::path::Path::new(RAIZ_SYSFS))\\n}", "#[cfg(target_os = \\"linux\\")]\\nfn probe_linux() -> Result<(), NetworkPolicyError> {\\n    // \\u00abrobustez\\u00bb: se a sonda nova n\\u00e3o decidir, cai para o algoritmo antigo (pre-R8.5b: s\\u00f3 wl*, s\\u00f3 `up`\\n    // \\u00e9 ativo, ileg\\u00edvel/dormant/unknown = inativo). Mant\\u00e9m probe_sysfs em uso (sem dead_code no clippy).\\n    match probe_sysfs(std::path::Path::new(RAIZ_SYSFS)) {\\n        Err(NetworkPolicyError::ProbeFailed { .. }) => {\\n            let mut ativas = Vec::new();\\n            if let Ok(entradas) = std::fs::read_dir(\\"/sys/class/net\\") {\\n                for e in entradas.flatten() {\\n                    let nome = e.file_name().to_string_lossy().to_string();\\n                    if !nome.starts_with(\\"wl\\") { continue; }\\n                    let st = std::fs::read_to_string(e.path().join(\\"operstate\\")).unwrap_or_default();\\n                    if st.trim() == \\"up\\" { ativas.push(nome); }\\n                }\\n            }\\n            if ativas.is_empty() { Ok(()) } else { Err(NetworkPolicyError::WifiActive { interfaces: ativas }) }\\n        }\\n        r => r,\\n    }\\n}", "r85c_l2_probe_linux_nao_tem_fallback"], "L3": ["#[cfg(target_os = \\"linux\\")]\\nfn probe_linux() -> Result<(), NetworkPolicyError> {\\n    probe_sysfs(std::path::Path::new(RAIZ_SYSFS))\\n}", "#[cfg(target_os = \\"linux\\")]\\nfn probe_linux() -> Result<(), NetworkPolicyError> {\\n    match probe_sysfs(std::path::Path::new(RAIZ_SYSFS)) {\\n        Err(NetworkPolicyError::ProbeFailed { .. }) => Ok(()),\\n        r => r,\\n    }\\n}", "r85c_l3_probe_failed_nao_vira_ok"], "L4": ["    #[cfg(target_os = \\"linux\\")]\\n    return probe_linux();", "    #[cfg(target_os = \\"linux\\")]\\n    return probe_linux().map_err(|e| match e {\\n        NetworkPolicyError::ProbeFailed { probe, error } => {\\n            NetworkPolicyError::ProbeUnavailable { reason: format!(\\"{probe}: {error}\\") }\\n        }\\n        outro => outro,\\n    });", "r85c_l4_probe_failed_nao_vira_unavailable"], "L5": ["    #[cfg(target_os = \\"linux\\")]\\n    return probe_linux();", "    #[cfg(target_os = \\"linux\\")]\\n    return {\\n        let _ = probe_linux();\\n        Ok(())\\n    };", "r85c_l5_resultado_da_sonda_nao_e_ignorado"], "L6": ["const RAIZ_SYSFS: &str = \\"/sys/class/net\\";", "const RAIZ_SYSFS: &str = \\"/sys/devices/virtual/net\\";", "r85c_l6_raiz_e_sys_class_net"]}')
NG = "crates/led-hal/src/network_guard.rs"
if sys.argv[1] == "teste":
    print(M[sys.argv[2]][2]); sys.exit(0)
a, b, _ = M[sys.argv[2]]
p = sys.argv[3] + "/" + NG
s = open(p).read()
assert s.count(a) == 1, ("ancora", s.count(a))
open(p, "w").write(s.replace(a, b))
print(sys.argv[2], "aplicado")
